package com.payflow.auth;
import com.payflow.common.ApiException; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/v1/auth") public class AuthController {private final MerchantUserRepository users;private final PasswordEncoder passwords;private final JwtService jwt;public AuthController(MerchantUserRepository u,PasswordEncoder p,JwtService j){users=u;passwords=p;jwt=j;}@PostMapping("/register") public Map<String,Object> register(@Valid @RequestBody Register r){if(users.existsByEmailIgnoreCase(r.email()))throw new ApiException(HttpStatus.CONFLICT,"Email is already registered");return response(users.save(new MerchantUser(r.email(),passwords.encode(r.password()),r.businessName())));}@PostMapping("/login") public Map<String,Object> login(@Valid @RequestBody Login r){var u=users.findByEmailIgnoreCase(r.email()).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"Invalid email or password"));if(!passwords.matches(r.password(),u.getPasswordHash()))throw new ApiException(HttpStatus.UNAUTHORIZED,"Invalid email or password");return response(u);}private Map<String,Object> response(MerchantUser u){return Map.of("token",jwt.create(u),"tokenType","Bearer","merchantId",u.getMerchantId(),"email",u.getEmail(),"businessName",u.getBusinessName(),"role",u.getRole());}public record Login(@Email @NotBlank String email,@NotBlank String password){}public record Register(@Email @NotBlank String email,@Size(min=8) String password,@NotBlank String businessName){}}
